// One shared, in-memory unlock for the two private workspaces.
function showProtectedUnlock(kind,unlock){
 const routine=kind==='routine',title=routine?'영적 일과':'봉사 보고',formId=routine?'routine-unlock':'ministry-unlock',inputId=routine?'routine-password':'ministry-password',errorId=routine?'routine-error':'ministry-error';
 $('#app').innerHTML=`<section class="workspace protected-page"><h1 class="people-title">${title}</h1><form id="${formId}" class="protected-form"><span class="protected-symbol" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="7.5" y="14" width="17" height="13" rx="3"/><path d="M11 14v-3a5 5 0 0 1 10 0v3M16 19v3"/></svg></span><label class="protected-field"><span class="sr-only">비밀번호</span><input id="${inputId}" type="password" inputmode="numeric" autocomplete="current-password" placeholder="비밀번호" required><button type="submit" class="protected-submit" aria-label="열기" title="열기">${UI_CHEVRON_RIGHT}</button></label><p id="${errorId}" class="protected-error" role="status" aria-live="polite"></p></form></section><a class="back bottom-back protected-back" href="#/home">← 처음</a>`;
 const form=document.getElementById(formId),input=document.getElementById(inputId),error=document.getElementById(errorId),button=form.querySelector('button');
 input.addEventListener('input',()=>{error.textContent=''});
 form.onsubmit=async e=>{e.preventDefault();button.disabled=true;input.disabled=true;error.textContent='';try{await unlock(input.value)}catch(err){if(form.isConnected){error.textContent=err.message||'연결 상태를 확인해 주세요.';input.disabled=false;input.focus();input.select()}}finally{if(form.isConnected){button.disabled=false;input.disabled=false}}};
}
